export function bounceOffBrick(ball, brick) {
  // penetration depths (how far the ball is inside the brick) per axis
  const penLeft = ball.x + ball.r - brick.x;
  const penRight = brick.x + brick.w - (ball.x - ball.r);
  const penTop = ball.y + ball.r - brick.y;
  const penBottom = brick.y + brick.h - (ball.y - ball.r);

  const penX = Math.min(penLeft, penRight);
  const penY = Math.min(penTop, penBottom);

  // The axis with the smaller penetration is the face hit:
  // top/bottom => flip vy, side => flip vx, equal => diagonal, flip both.
  if (penX < penY) {
    ball.vx = -ball.vx;
  } else if (penY < penX) {
    ball.vy = -ball.vy;
  } else {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  }

  // push out along the axes that penetrate
  if (penX > 0) {
    // push horizontally out of the brick
    const dx = penLeft <= penRight ? -penX : penX;
    ball.x += dx;
  }
  if (penY > 0) {
    const dy = penTop <= penBottom ? -penY : penY;
    ball.y += dy;
  }
