**Segment vs inflated AABB (Liang-Barsky):**

```
export function sweepHit(px, py, ball, brick) {
  const r = ball.r;
  const minX = brick.x - r, maxX = brick.x + brick.w + r;
  const minY = brick.y - r, maxY = brick.y + brick.h + r;

  const dx = ball.x - px;
  const dy = ball.y - py;

  let tIn = 0, tOut = 1;
  let face = null;

  // X slab
  if (dx === 0) {
    if (ball.x < minX || ball.x > maxX) return null;
  } else {
    let t1 = (minX - px) / dx;
    let t2 = (maxX - px) / dx;
    if (t1 > t2) [t1, t2] = [t2, t1];
    if (t2 < tIn || t1 > tOut) return null;
    if (t1 > tIn) { tIn = t1; face = 'x'; }
    tOut = Math.min(tOut, t2);
  }

  // Y slab
  if (dy === 0) {
    if (ball.y < minY || ball.y > maxY) return null;
  } else {
    let t1 = (minY - py) / dy;
    let t2 = (maxY - py) / dy;
