// Swept collision: does the segment (px,py) → (ball.x,ball.y) cross the
// region the ball's body sweeps over the brick (the brick inflated by r)?
// Returns null or { face: 'x' | 'y' | 'both', x, y } — the first-contact
// position (ball center) and the face crossed there.
export function sweepHit(px, py, ball, brick) {
  const r = ball.r;
  const x0 = brick.x - r;
  const x1 = brick.x + brick.w + r;
  const y0 = brick.y - r;
  const y1 = brick.y + brick.h + r;

  const dx = ball.x - px;
  const dy = ball.y - py;

  let tIn = 0;
  let tOut = 1;
  let faceX = null; // the X-slab entry time (as a candidate)
  let faceY = null;

  // X slab
  if (dx === 0) {
    if (ball.x < x0 || ball.x > x1) return null;
  } else {
    let t1 = (x0 - px) / dx;
    let t2 = (x1 - px) / dx;
    if (t1 > t2) [t1, t2] = [t2, t1];
    if (t2 < 0 || t1 > 1) return null;   // no overlap in [0,1]
    tIn = Math.max(tIn, t1);
    tOut = Math.min(tOut, t2);
    faceX = t1;
  }

  // Y slab
  if (dy === 0) {
    if (ball.y < y0 || ball.y > y1) return null;
  } else {
    let t1 = (y0 - py) / dy;
    let t2 = (y1 - py) / dy;
    if (t1 > t2) [t1, t2] = [t2, t1];
    if (t2 < 0 || t1 > 1) return null;
    tIn = Math.max(tIn, t1);
    tOut = Math.min(tOut, t2);
    faceY = t1;
  }

  if (tIn > tOut) return null;

  let face;
  const fx = faceX === null ? -Infinity : faceX;
  const fy = faceY === null ? -Infinity : faceY;
  if (fx > fy) face = 'x';
  else if (fy > fx) face = 'y';
  else face = 'both';

  return { face, x: px + dx * tIn, y: py + dy * tIn };
}
