```js
// --- Brick collision (pure, testable) --------------------------------------

// Resolves a single ball/brick overlap: flips the velocity component(s) on the
// face(s) that were hit and pushes the ball back out of the brick.
// - per face: the axis with the SMALLER penetration is the face hit — flip vy
//   on a top/bottom hit, vx on a side hit, leave the other component alone;
// - corner: equal penetrations means a diagonal hit — flip both;
// - push out: the ball is repositioned outside the brick so the bounce cannot
//   re-trigger on the next frame (sticky bounce).
// Mutates `ball`. No-op unless the ball actually overlaps the brick.
export function bounceOffBrick(ball, brick) {
  const penLeft = ball.x + ball.r - brick.x;
  const penRight = brick.x + brick.w - (ball.x - ball.r);
  const penTop = ball.y + ball.r - brick.y;
  const penBottom = brick.y + brick.h - (ball.y - ball.r);

  const penX = Math.min(penLeft, penRight);
  const penY = Math.min(penTop, penBottom);
  if (penX <= 0 || penY <= 0) return;

  if (penX < penY) {
    ball.vx = -ball.vx;      // side hit
  } else if (penY < penX) {
    ball.vy = -ball.vy;      // top / bottom hit
  } else {
    ball.vx = -ball.vx;      // diagonal hit
    ball.vy = -ball.vy;
  }

  // Push out along the penetrating axes.
  ball.x += penLeft <= penRight ? -penX : penX;
  ball.y += penTop <= penBottom ? -penY : penY;
}
```

