```js
// Swept collision: does the ball, moving from (px, py) to (ball.x, ball.y),
// cross the region swept by its body over the brick (the brick inflated by
// the ball radius)? Catches tunnelling: at high speed the ball can jump from
// one side of a brick to the other in a single step, so checking the start
// and end positions alone misses the brick entirely.
// Returns null when there is no crossing, otherwise
// { face: 'x' | 'y' | 'both', x, y } — the face crossed at first contact and
// the ball-centre position where the ball first touches the brick.
export function sweepHit(px, py, ball, brick) {
  const r = ball.r;
  const x0 = brick.x - r;
  const x1 = brick.x + brick.w + r;
  const y0 = brick.y - r;
  const y1 = brick.y + brick.h + r;

  const dx = ball.x - px;
  const dy = ball.y - py;

  let tIn = 0;
  let tOut = 1;
  let entryX = null; // entry time of the X slab (null: never crossed)
  let entryY = null;

  if (dx === 0) {
    if (ball.x < x0 || ball.x > x1) return null;
  } else {
    let t1 = (x0 - px) / dx;
    let t2 = (x1 - px) / dx;
    if (t1 > t2) [t1, t2] = [t2, t1];
    if (t2 < 0 || t1 > 1) return null;
    entryX = t1;
    tIn = Math.max(tIn, t1);
    tOut = Math.min(tOut, t2);
  }

  if (dy === 0) {
    if (ball.y < y0 || ball.y > y1) return null;
  } else {
    let t1 = (y0 - py) / dy;
    let t2 = (y1 - py) / dy;
    if (t1 > t2) [t1, t2] = [t2, t1];
    if (t2 < 0 || t1 > 1) return null;
    entryY = t1;
    tIn = Math.max(tIn, t1);
    tOut = Math.min(tOut, t2);
  }

  // The segment must ENTER the swept region strictly inside the step:
  // a crossing that starts at t = 0 is the ball leaving a face it was already
  // resting against (after a bounce), not a new impact.
  if (tIn <= 0 || tIn > tOut || tIn > 1) return null;

  const fx = entryX === null ? -Infinity : entryX;
  const fy = entryY === null ? -Infinity : entryY;
  let face;
  if (fx > fy) face = 'x';
  else if (fy > fx) face = 'y';
  else face = 'both';

  return { face, x: px + dx * tIn, y: py + dy * tIn };
}
```

