Now `collideBricks`:

```js
// One collision pass for the frame: finds every brick the ball touches (by
// direct overlap OR by swept crossing from the previous position), destroys
// them, awards score/combo, and bounces the ball exactly ONCE — the grid gaps
// are 8 px wide against a 14 px ball, so a seam hit overlaps two bricks in
// the same pass; flipping the velocity for each would cancel out and let the
// ball through (a double flip is a no-op).
// Pure: no DOM access, no rendering. Mutates `state`.
export function collideBricks(state) {
  const ball = state.ball;
  const px = ball.px ?? ball.x;
  const py = ball.py ?? ball.y;

  const hits = [];
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    if (collides(ball, brick)) {
      hits.push({ brick, swept: null });
    } else {
      const swept = sweepHit(px, py, ball, brick);
      if (swept) hits.push({ brick, swept });
    }
  }
  if (hits.length === 0) return;

  for (const { brick } of hits) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  const first = hits[0];
  if (first.swept) {
    ball.x = first.swept.x;
    ball.y = first.swept.y;
    if (first.swept.face === 'x') ball.vx = -ball.vx;
    else if (first.swept.face === 'y') ball.vy = -ball.vy;
    else { ball.vx = -ball.vx; ball.vy = -ball.vy; }
  } else {
    bounceOffBrick(ball, first.brick);
  }
}
```

