const firstBrick = () => makeBricks(1)[0];

test('bounceOffBrick: side hit flips vx, leaves vy alone, pushes out', () => {
  const brick = firstBrick();
  const ball = { x: 8, y: 58, r: 7, vx: 300, vy: 0 };
  assert.equal(collides(ball, brick), true);
  bounceOffBrick(ball, brick);
  assert.equal(ball.vx, -300, 'side hit flips vx');
  assert.equal(ball.vy, 0, 'the other component stays exactly as it was');
  assert.equal(ball.x, -3, 'pushed out along the hit axis');
  assert.equal(ball.y, 58, 'slides along the face: y untouched');
  assert.equal(collides(ball, brick), false, 'no overlap left (no sticky bounce)');
});

test('bounceOffBrick: top/bottom hit flips vy, leaves vx alone, pushes out', () => {
  const brick = firstBrick();
  const ball = { x: 40, y: 44, r: 7, vx: 0, vy: 300 };
  assert.equal(collides(ball, brick), true);
  bounceOffBrick(ball, brick);
  assert.equal(ball.vy, -300, 'top hit flips vy');
  assert.equal(ball.vx, 0, 'the other component stays exactly as it was');
  assert.equal(ball.y, 41, 'pushed out along the hit axis');
  assert.equal(ball.x, 40, 'slides along the face: x untouched');
  assert.equal(collides(ball, brick), false, 'no overlap left (no sticky bounce)');
});

test('bounceOffBrick: corner (equal penetration) flips both components', () => {
  const brick = firstBrick();
  const ball = { x: 4, y: 48, r: 7, vx: 300, vy: -300 };
  assert.equal(collides(ball, brick), true);
  bounceOffBrick(ball, brick);
  assert.equal(ball.vx, -300, 'diagonal hit flips vx');
  assert.equal(ball.vy, 300, 'diagonal hit flips vy');
  assert.equal(collides(ball, brick), false, 'no overlap left (no sticky bounce)');
});

test('collideBricks: seam hit bounces exactly once, both bricks break', () => {
  const state = createState(1);
  const a = state.bricks[1]; // row 0, col 1 — x: 84
  const b = state.bricks[2]; // row 0, col 2 — x: 164
  // The ball (14 px across) straddles the 8 px gap: it overlaps both bricks
  // in the same pass. Two flips would cancel out and let it through.
  state.ball = { x: 160, y: 74, r: 7, vx: 0, vy: -260, px: 160, py: 80 };
  collideBricks(state);
  assert.equal(a.alive, false, 'left brick destroyed');
  assert.equal(b.alive, false, 'right brick destroyed');
  assert.equal(state.ball.vy, 260, 'vy flipped exactly once');
  assert.equal(state.ball.vx, 0, 'vx untouched');
});

test('collideBricks: corner of four bricks flips both components once', () => {
  const state = createState(1);
  const quad = [1, 2, 9, 10].map((i) => state.bricks[i]);
  state.ball = { x: 160, y: 72, r: 7, vx: 130, vy: -260, px: 160, py: 80 };
  collideBricks(state);
  assert.ok(quad.every((bk) => !bk.alive), 'all four bricks destroyed');
  assert.equal(state.ball.vx, -130, 'vx flipped exactly once');
  assert.equal(state.ball.vy, 260, 'vy flipped exactly once');
});

test('sweepHit: crossing between two non-overlapping positions is a hit', () => {
  const brick = firstBrick();
  // Ball below the brick (bottom face + r = 75), teleporting past it.
  const ball = { x: 40, y: 40.5, r: 7 };
  const hit = sweepHit(40, 76, ball, brick);
  assert.ok(hit, 'fast ball jumps over the brick');
  assert.equal(hit.face, 'y', 'crossed the top/bottom face');
  assert.ok(Math.abs(hit.y - 75) < 0.01, 'contact rests against the face');
});

test('sweepHit: ball leaving a face it rests on is not a new impact', () => {
