edits.oldText:
// --- Collision (tested primitive) ------------------------------------------

// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The missing bounce in frame() is what lets the ball plow
// straight through bricks (see #1).

edits.newText:
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Resolves a single ball/brick overlap. The axis with the SMALLER penetration
// is the face that was hit:
//   - top/bottom hit  -> flip vy, leave vx alone;
//   - side hit        -> flip vx, leave vy alone;
//   - equal           -> diagonal hit, flip both components.
// The ball is then pushed back OUT of the brick along the hit axis so it does
// not overlap on the next frame (otherwise the bounce re-triggers forever —
// the sticky bounce). Mutates `ball`; no-op unless the ball really overlaps.
export function bounceOffBrick(ball, brick) {
  const penLeft = ball.x + ball.r - brick.x;
  const penRight = brick.x + brick.w - (ball.x - ball.r);
  const penTop = ball.y + ball.r - brick.y;
  const penBottom = brick.y + brick.h - (ball.y - ball.r);

  const penX = Math.min(penLeft, penRight);
  const penY = Math.min(penTop, penBottom);
  if (penX <= 0 || penY <= 0) return;

  if (penX < penY) {
    // Side hit: bounce horizontally, slide along the face.
    ball.vx = -ball.vx;
    ball.x += penLeft <= penRight ? -penX : penX;
  } else if (penY < penX) {
    // Top/bottom hit: bounce vertically, slide along the face.
    ball.vy = -ball.vy;
    ball.y += penTop <= penBottom ? -penY : penY;
  } else {
    // Corner: diagonal hit, bounce and push out on both axes.
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x += penLeft <= penRight ? -penX : penX;
    ball.y += penTop <= penBottom ? -penY : penY;
  }
}

// Swept collision: does the ball, moving from (px, py) to (ball.x, ball.y),
// cross the region swept by its body over the brick (the brick inflated by
// the ball radius)? At high speed the ball jumps more than a brick thickness
// per frame (35.5 px at level 6 vs the 34 px needed to cross a brick), so
// checking only the start and end positions misses the brick entirely — the
// ball tunnels through.
// Returns null when there is no crossing, otherwise
//   { face: 'x' | 'y' | 'both', x, y } — the face crossed at first contact
//   and the ball-centre position where the ball first touches the brick.
export function sweepHit(px, py, ball, brick) {
  const r = ball.r;
  const x0 = brick.x - r;
  const x1 = brick.x + brick.w + r;
  const y0 = brick.y - r;
  const y1 = brick.y + brick.h + r;

  const dx = ball.x - px;
  const dy = ball.y - py;

  let tIn = 0;
  let tOut = 1;
  let entryX = null; // when the segment enters the X slab (null: never)
  let entryY = null;

  if (dx === 0) {
    if (ball.x < x0 || ball.x > x1) return null;
  } else {
    let t1 = (x0 - px) / dx;
    let t2 = (x1 - px) / dx;
    if (t1 > t2) [t1, t2] = [t2, t1];
    if (t2 < 0 || t1 > 1) return null;
    entryX = t1;
    tIn = Math.max(tIn, t1);
    tOut = Math.min(tOut, t2);
  }

  if (dy === 0) {
    if (ball.y < y0 || ball.y > y1) return null;
  } else {
    let t1 = (y0 - py) / dy;
    let t2 = (y1 - py) / dy;
    if (t1 > t2) [t1, t2] = [t2, t1];
    if (t2 < 0 || t1 > 1) return null;
    entryY = t1;
    tIn = Math.max(tIn, t1);
    tOut = Math.min(tOut, t2);
  }

  // The segment must ENTER the swept region strictly inside the step. A
  // crossing starting at t = 0 means the ball was already resting against the
  // brick's face when the step began (right after a bounce) and is now moving
  // away: that is not a new impact, and bouncing again would cancel the
  // previous flip (sticky bounce).
  if (tIn <= 0 || tIn > tOut) return null;

  const fx = entryX === null ? -Infinity : entryX;
  const fy = entryY === null ? -Infinity : entryY;
  let face;
  if (fx > fy) face = 'x';
  else if (fy > fx) face = 'y';
  else face = 'both';

  return { face, x: px + dx * tIn, y: py + dy * tIn };
}

// One collision pass for the frame. Destroys every brick the ball touches
// this step — by direct overlap OR by swept crossing from the previous
// position — awards score/combo, and bounces the ball exactly ONCE (against
// the first touched brick). The bounce must not repeat per brick: the grid
// gap is 8 px against a 14 px ball, so a seam hit overlaps two bricks in the
// same pass, and `vy = -vy` applied twice cancels out — the ball would go
// through. Pure: no DOM, no rendering. Mutates `state`.
export function collideBricks(state) {
  const ball = state.ball;
  const px = ball.px ?? ball.x;
  const py = ball.py ?? ball.y;

  const hits = [];
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    if (collides(ball, brick)) {
      hits.push({ brick, swept: null });
    } else {
      const swept = sweepHit(px, py, ball, brick);
      if (swept) hits.push({ brick, swept });
    }
  }
  if (hits.length === 0) return;

  for (const { brick } of hits) {
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  const first = hits[0];
  if (first.swept) {
    // Tunnelling: park the ball at the first-contact point (it just touches
    // the brick, so the bounce cannot re-trigger), then flip the face(s).
    ball.x = first.swept.x;
    ball.y = first.swept.y;
    if (first.swept.face === 'x') ball.vx = -ball.vx;
    else if (first.swept.face === 'y') ball.vy = -ball.vy;
    else {
      ball.vx = -ball.vx;
      ball.vy = -ball.vy;
    }
  } else {
    bounceOffBrick(ball, first.brick);
  }
}

