+    } else {
+      const swept = sweepHit(px, py, ball, brick);
+      if (swept) hits.push({ brick, swept });
+    }
+  }
+  if (hits.length === 0) return;
+
+  for (const { brick } of hits) {
+    brick.alive = false;
+    state.combo += 1;
+    state.score += scoreForBrick(brick, state.combo);
